#!/usr/bin/env python3
#
# tools/rfc_decode.py - decode the SAU2 domain_os RFC image the way the
# loader (sysboot) and COLD_START see it, and write tools/rfc_segments.json
# (docs/rfc-cold-start.md explains every field; bead source-10hr)
#
# Generated by: Claude Opus 5.5; reviewed against the bytes 2026-10-06 by
# Claude Fable 5.1 (IODEFS_GUARD follows the bss 'loaded at' rule, not VA)
#
# Usage:
#   rfc_decode.py --image IMG --map MAP [--asm-ref tools/asm_image_ref.txt]
#                 [-o tools/rfc_segments.json]
#
# Everything is read from the image; the only kernel constants used are the
# ones COLD itself carries (its absolute operands are read out of the COLD
# code bytes at the addresses named below), so the same script works on the
# 10.3 image (different link constants, same COLD).

import argparse
import json
import re
import struct
import sys

LOAD = 0x101400          # RFC header word 0: file byte 0 lands here


def be32(d, a):
    return struct.unpack('>I', d[a - LOAD:a - LOAD + 4])[0]


def be16(d, a):
    return struct.unpack('>H', d[a - LOAD:a - LOAD + 2])[0]


# COLD operands (instruction address + 2 = immediate), identical in 10.2/10.3
OP_RELOC_VA = 0x101496       # moveal #RELOC,%a0
OP_KERNEL_VA = 0x10149C      # subal  #0xE00800,%a0
OP_KERNEL_LOW = 0x1014A2     # addal  #0x102000,%a0
OP_SPLIT_LOW = 0x1014A8      # cmpal  #0x157C00,%a0
OP_PAGE_END = 0x101592       # movel  #OS_PAGE_END,%d4
OP_LO_BYTES = 0x1015A8       # cmpl   #0x55C00,%d4
OP_MMAP_VA = 0x1015E6        # addl   #MMAP,%d4
OP_PTTX_VA = 0x10176A        # addal  #MMU_$PTTX,%a1
OP_STACK = 0x1016FA          # moveal #P1_STACK_BASE,%sp
OP_ENTRY = 0x101708          # moveal #OS_$INIT,%a0
MOVE_TO_PPN = 0x101420
MAP_TABLE = 0x101850
MAP_LO_COUNT = 0x1018E6      # written by COLD at 0x1015B4
MAP_HI_COUNT_PPN = 0x1018F0  # written by COLD at 0x1015CC

# RELOC windows (COLD 0x1014C4..0x101538): (lo, hi, delta) on the value
# masked with 0x3FFFFFF; only applied when PROM byte 0x103 bit 1 is set.
WINDOWS = [(0xE00000, 0xFA0000, 0x2F00000), (0xFA0000, 0x4000000, 0x3000000),
           (0xCC0000, 0xE00000, 0x2E00000), (0x700000, 0x800000, -0x300000)]


def parse_map(path):
    segs = []
    pat = re.compile(r'^([ID])\s*(\d+)\s+([0-9A-F]+)\s+(\S+)\s+loaded at\s+'
                     r'([0-9A-F]+), size = ([0-9A-F]+)')
    for line in open(path):
        m = pat.match(line)
        if m:
            segs.append(dict(kind=m.group(1), num=int(m.group(2)),
                             va=int(m.group(3), 16), name=m.group(4),
                             loaded_at=int(m.group(5), 16),
                             size=int(m.group(6), 16)))
    return segs


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--image', required=True)
    ap.add_argument('--map', required=True)
    ap.add_argument('--asm-ref')
    ap.add_argument('-o', '--output')
    a = ap.parse_args()
    d = open(a.image, 'rb').read()
    end_low = LOAD + len(d)

    # RFC header: load.l, start.l, machine.w (n of SAUn), then a word that
    # is 0 in every sau2 file (00 02 00 00)
    hdr = dict(load=be32(d, LOAD), start=be32(d, LOAD + 4),
               machine=be16(d, LOAD + 8), header_word_10=be16(d, LOAD + 10))
    info = dict(kernel_offset=be32(d, 0x10140C), data_va=be32(d, 0x101410),
                kernel_va=be32(d, 0x101414), magic=be32(d, 0x101418),
                split_ppn=be32(d, 0x10141C), move_to_ppn=be32(d, MOVE_TO_PPN))
    assert hdr['load'] == LOAD and (info['magic'] >> 16) == 0xFEED

    reloc_va = be32(d, OP_RELOC_VA)
    kva = be32(d, OP_KERNEL_VA)
    klow = be32(d, OP_KERNEL_LOW)
    split = be32(d, OP_SPLIT_LOW)
    page_end = be32(d, OP_PAGE_END)
    lo_bytes = be32(d, OP_LO_BYTES)
    assert split == info['split_ppn'] << 10 and klow == LOAD + info['kernel_offset']
    assert kva == info['kernel_va'] and lo_bytes == split - klow
    move = info['move_to_ppn'] << 10
    delta = kva - klow                     # VA - low address, whole file

    def phys(low):                          # where sysboot put a file byte
        return low if low < split else low - split + move

    # COLD's MMU map table, with the two cells COLD fills in at run time
    pages = ((page_end + 0x3FF) & ~0x3FF) - kva
    lo_cnt, hi_cnt = (pages >> 10, 0) if pages <= lo_bytes else \
        (lo_bytes >> 10, (pages - lo_bytes) >> 10)
    entries = []
    a_ = MAP_TABLE
    while True:
        cnt = be16(d, a_)
        if a_ == MAP_LO_COUNT:
            cnt = lo_cnt
        ppn = be16(d, a_ + 2)
        if a_ == MAP_HI_COUNT_PPN:
            cnt, ppn = hi_cnt, info['move_to_ppn']
        if cnt == 0:
            break
        va = be32(d, a_ + 4)
        entries.append(dict(at=hex(a_), count=cnt, ppn=hex(ppn),
                            phys=hex(ppn << 10), va=hex(va & 0x1FFFFFFF),
                            va_flags=hex(va >> 29), prot=hex(be16(d, a_ + 8)),
                            bytes=hex(cnt << 10)))
        a_ += 10

    # RELOC table
    t = reloc_va - delta
    n = be16(d, t)
    cells = [be32(d, t + 2 + 4 * i) for i in range(n)]
    counts = {}
    for c in cells:
        v = be32(d, c) & 0x3FFFFFF
        k = 'none'
        for lo, hi, dl in WINDOWS:
            if lo <= v < hi:
                k = '%X..%X %+X' % (lo, hi, dl)
                break
        counts[k] = counts.get(k, 0) + 1

    # file regions
    regions = [
        dict(name='RFC header', low=hex(LOAD), size=hex(12)),
        dict(name='info block', low=hex(LOAD + 12), size=hex(24)),
        dict(name='COLD code+data', low=hex(LOAD + 0x24), end=hex(LOAD + 0x800),
             note='map: D22 COLD size 7FC; 0x101BFC..0x101C00 is the stack top pad'),
        dict(name='DUMP', low=hex(LOAD + 0x800), va='0xE00400', size='0x400',
             phys_runtime='0x100C00 (copied by COLD 0x10154E)'),
        dict(name='kernel', low=hex(klow), end=hex(reloc_va - delta),
             va=hex(kva), va_end=hex(reloc_va), va_minus_low=hex(delta)),
        dict(name='RELOC', low=hex(t), end=hex(end_low), entries=n,
             table_end=hex(t + 2 + 4 * n),
             zero_pad=hex(end_low - (t + 2 + 4 * n))),
    ]

    segs = []
    for s in parse_map(a.map):
        va, size = s['va'], s['size']
        if va < kva - 0x400:
            where = 'absolute (loaded at = VA, not in file)'
            low = None
        elif va < reloc_va:
            low = va - delta
            where = 'file'
        else:
            low = None
            where = 'bss (not in file; RAM after the image, never zeroed by COLD)'
        e = dict(name=s['name'], kind=s['kind'], num=s['num'], va=hex(va),
                 size=hex(size), map_loaded_at=hex(s['loaded_at']), where=where)
        if low is not None:
            e['low'] = hex(low)
            e['file_offset'] = hex(low - LOAD)
            e['phys_runtime'] = hex(phys(low))
            e['map_agrees'] = (low == s['loaded_at'])
        elif where.startswith('bss'):
            e['phys_runtime'] = hex(va - (kva + lo_bytes) + move)
            e['map_loaded_at_note'] = 'binder stream position = VA - %s + RELOC size' % hex(delta)
        segs.append(e)

    hits = []
    if a.asm_ref:
        for line in open(a.asm_ref):
            if line.startswith('#') or not line.strip():
                continue
            va_s, _, hx = line.split()
            va, b = int(va_s, 16), bytes.fromhex(hx)
            pos, i = [], d.find(b)
            while i >= 0:          # overlapping matches
                pos.append(i + LOAD)
                i = d.find(b, i + 1)
            hits.append(dict(va=hex(va), len=len(b), low_expected=hex(va - delta),
                             found=[hex(p) for p in pos[:4]],
                             ok=(va - delta) in pos))

    out = dict(image=a.image, size=len(d), header={k: hex(v) for k, v in hdr.items()},
               info={k: hex(v) for k, v in info.items()},
               cold_constants=dict(reloc_va=hex(reloc_va), kernel_va=hex(kva),
                                   kernel_low=hex(klow), split_low=hex(split),
                                   move_to_phys=hex(move), os_page_end=hex(page_end),
                                   mmap_va=hex(be32(d, OP_MMAP_VA)),
                                   pttx_va=hex(be32(d, OP_PTTX_VA)),
                                   initial_sp=hex(be32(d, OP_STACK)),
                                   entry=hex(be32(d, OP_ENTRY))),
               file_regions=regions, mmu_map_table=entries,
               reloc=dict(entries=n, window_counts=counts,
                          cells_below_kernel=[hex(c) for c in cells if c < klow]),
               map_segments=segs,
               asm_ref_hits=dict(total=len(hits), ok=sum(h['ok'] for h in hits),
                                 runs=hits))
    txt = json.dumps(out, indent=1) + '\n'
    if a.output:
        open(a.output, 'w').write(txt)
    else:
        sys.stdout.write(txt)
    bad = [s for s in segs if s.get('map_agrees') is False]
    print('header %s; %d MMU map entries; RELOC %d cells; %d/%d asm-ref runs at '
          'VA-%s; %d file segments disagree with the map' %
          (out['header'], len(entries), n, out['asm_ref_hits']['ok'], len(hits),
           hex(delta), len(bad)), file=sys.stderr)
    return 1 if bad or out['asm_ref_hits']['ok'] != len(hits) else 0


if __name__ == '__main__':
    sys.exit(main())
